import { Type } from '@sinclair/typebox';

const updateOrgSchema = {
  params: Type.Object({
    orgId: Type.String({ format: 'uuid' })
  }),
  body: Type.Object({
    displayName: Type.String({ minLength: 2 }),
    billingEmail: Type.String({ format: 'email' })
  })
};

fastify.put('/api/v1/organizations/:orgId/settings', {
  schema: updateOrgSchema,
  preHandler: [fastify.authenticate]
}, async (request, reply) => {
  const { orgId } = request.params;
  const { displayName, billingEmail } = request.body;

  const membership = await prisma.organizationMember.findFirst({
    where: {
      organizationId: orgId,
      userId: request.user.id,
      role: { in: ['OWNER', 'ADMIN'] }
    }
  });
  if (!membership) {
    return reply.status(403).send({ error: 'Forbidden: insufficient privileges on target organization' });
  }

  const updated = await prisma.organization.update({
    where: { id: orgId },
    data: { displayName, billingEmail }
  });

  return reply.send({ success: true, organization: updated });
});
